import {pipeline,env,TextStreamer} from '@huggingface/transformers';
import wasmFactory from '../../node_modules/onnxruntime-web/dist/ort-wasm-simd-threaded.asyncify.mjs?url';
import wasmBinary from '../../node_modules/onnxruntime-web/dist/ort-wasm-simd-threaded.asyncify.wasm?url';
import cpuFactory from '../../node_modules/onnxruntime-web/dist/ort-wasm-simd-threaded.mjs?url';
import cpuBinary from '../../node_modules/onnxruntime-web/dist/ort-wasm-simd-threaded.wasm?url';
import {LOCAL_MODEL,LOCAL_MODEL_CACHE,runLocalTask} from './local-ai-tasks.js';

env.allowLocalModels=false;
env.cacheKey=LOCAL_MODEL_CACHE;
env.backends.onnx.wasm.numThreads=1; // Phones need no cross-origin isolation or SharedArrayBuffer.
env.backends.onnx.wasm.proxy=false;
let generator,backend;
const send=(id,value)=>self.postMessage({id,...value});
const metadataUrl=new URL('/__local-ai-ready',self.location.origin).href;
const gpuError=/webgpu|shader|gpu|backend|device lost|adapter/i;
// The phone's graphics chip is used when it can run the model; otherwise, or once it has failed here, the processor runs it.
// The user never picks: a failed graphics start is remembered beside the model and the processor takes over at once.
async function prepare(id){
  if(generator)return;
  let gpuFailed=false;
  try{gpuFailed=!!(await (await caches.open(LOCAL_MODEL_CACHE)).match(metadataUrl).then(response=>response?.json()))?.gpuFailed;}catch{}
  try{await load(id,gpuFailed?'wasm':'auto');}
  catch(error){
    if(backend!=='webgpu'||!gpuError.test(String(error.message||error)))throw error;
    generator=null;gpuFailed=true;
    send(id,{type:'progress',phase:'loading',message:'Видеоускорение не запустилось, переходим на процессор…'});
    await load(id,'wasm');
  }
  let downloaded=false;
  try{
    const cache=await caches.open(LOCAL_MODEL_CACHE),keys=await cache.keys();
    downloaded=keys.some(key=>key.url.includes('.onnx'));
    if(downloaded)await cache.put(metadataUrl,new Response(JSON.stringify({revision:LOCAL_MODEL.revision,backend,gpuFailed}),{headers:{'Content-Type':'application/json'}}));
  }catch{}
  send(id,{type:'progress',phase:'ready',device:backend,downloadedModel:downloaded,message:downloaded?'Модель готова к работе без интернета':'Модель готова; браузер не сохранил её для офлайн-работы'});
}
async function load(id,preferred){
  const files=new Map();let lastProgress=0;
  const progress=value=>{
    if(value.file&&value.total)files.set(value.file,{loaded:value.loaded||0,total:value.total});
    const downloaded=[...files.values()].reduce((sum,file)=>sum+file.loaded,0),total=[...files.values()].reduce((sum,file)=>sum+file.total,0);
    if(value.status==='progress'&&Date.now()-lastProgress<150)return;
    lastProgress=Date.now();
    send(id,{type:'progress',phase:'loading',downloaded,total,message:downloaded&&downloaded<total?'Скачиваем модель…':'Подготавливаем модель…'});
  };
  let adapter;
  if(preferred!=='wasm'&&navigator.gpu)try{adapter=await navigator.gpu.requestAdapter();}catch{}
  backend=adapter?.features.has('shader-f16')?'webgpu':'wasm';
  adapter?.destroy?.();
  // A single-threaded CPU fallback also works in browsers without WebGPU.
  // Old Safari cannot use asyncify; both runtime variants ship with the site.
  const oldSafari=/Version\/(\d+).*Safari/.exec(navigator.userAgent);
  const legacyCpu=backend==='wasm'&&oldSafari&&Number(oldSafari[1])<26;
  env.backends.onnx.wasm.wasmPaths={mjs:legacyCpu?cpuFactory:wasmFactory,wasm:legacyCpu?cpuBinary:wasmBinary};
  send(id,{type:'progress',phase:'loading',device:backend,message:'Подготавливаем модель…'});
  generator=await pipeline('text-generation',LOCAL_MODEL.id,{
    revision:LOCAL_MODEL.revision,device:backend,dtype:backend==='webgpu'?'q4f16':'q8',
    local_files_only:navigator.onLine===false,progress_callback:progress,
  });
  // Warm up now, rather than reporting success before the first inference works.
  await generator([{role:'user',content:'Ответь: да /no_think'}],{max_new_tokens:2,do_sample:false,tokenizer_encode_kwargs:{enable_thinking:false}});
}

let busy=false;
self.onmessage=async({data:{id,action,input={}}})=>{
  if(busy){send(id,{type:'error',message:'Локальная модель уже выполняет задачу.'});return;}
  busy=true;
  try{
    const started=performance.now();
    await prepare(id);
    const prepared=performance.now();
    if(action==='prepare'){send(id,{type:'result',result:{device:backend}});return;}
    let tokens=0,lastUpdate=0;
    const generate=async(messages,options)=>{
      const inputTokens=generator.tokenizer.apply_chat_template(messages,{tokenize:true,add_generation_prompt:true,enable_thinking:false});
      if(inputTokens.length>2048)throw Error('Слишком длинный текст или контекст для телефона. Сократите его и повторите.');
      const before=tokens;
      const output=await generator(messages,{...options,do_sample:false,tokenizer_encode_kwargs:{enable_thinking:false},streamer:new TextStreamer(generator.tokenizer,{skip_prompt:true,skip_special_tokens:true,callback_function:()=>{},token_callback_function:()=>{tokens++;if(Date.now()-lastUpdate>500){send(id,{type:'progress',phase:'generating',tokens});lastUpdate=Date.now();}}})});
      if(tokens-before>=options.max_new_tokens)throw Error('Ответ слишком длинный. Разделите текст на меньшие части.');
      return output[0].generated_text.at(-1).content;
    };
    const result=await runLocalTask(action,input,{generate,onProgress:progress=>send(id,{type:'progress',phase:'generating',tokens,...progress})});
    send(id,{type:'result',result,metrics:{action,prepareMs:prepared-started,taskMs:performance.now()-prepared,items:action==='translateText'?input.items.length:result.schedule.length,languages:action==='translateText'?input.targetLangs.length:0}});
  }catch(error){
    const message=String(error.message||error);
    const detail=/memory|allocation|buffer|out of bounds/i.test(message)?'Не хватает памяти. Закройте другие вкладки или выберите Gemini.':/fetch|network|offline|locally|file.*not found|unavailable/i.test(message)?'Не удалось загрузить модель. Для первой загрузки нужен интернет. Если модель уже скачана, проверьте свободное место.':gpuError.test(message)?'Модель не запустилась на этом устройстве. Выберите Gemini.':message;
    send(id,{type:'error',message:detail,code:'LOCAL_AI_ERROR',recoverable:!!generator&&!/memory|allocation|buffer|out of bounds/i.test(message)&&!gpuError.test(message)});
  }finally{busy=false;}
};
